const s = state({ bpm: 100, running: false, beat: 0 })
let timer = null

const start = () => {
  clearInterval(timer)
  timer = setInterval(() => {
    s.beat = (s.beat % 4) + 1
    audio.tone(s.beat === 1 ? 1500 : 1000, 0.05, { wait: false })
    haptic(s.beat === 1 ? "heavy" : "light")
  }, 60000 / s.bpm)
}

ui.render(() =>
  VStack({ spacing: 24 },
    Text(`${Math.round(s.bpm)} BPM`).font(54, "bold", "rounded"),
    HStack({ spacing: 14 }, ForEach([1, 2, 3, 4], b => Circle().fill(s.running && s.beat === b ? "green" : "gray").frame({ width: 28, height: 28 }))),
    Slider(s.bpm, v => { s.bpm = v; if (s.running) start() }, { min: 40, max: 220, step: 1 }),
    Button(s.running ? "Stop" : "Start", () => {
      s.running = !s.running
      s.running ? start() : clearInterval(timer)
    }).buttonStyle("borderedProminent").controlSize("large"),
  ).padding(24)
)

