    ),
    Card(Text("This week").font("headline"), Chart(points, { type: "line" })),
    Map({ latitude: loc.latitude, longitude: loc.longitude, span: 0.2, pins: [{ ...loc, title: "You" }] }).cornerRadius(16),
  ).padding()
)

