const word = input("Word to look up", clipboard.get() || "serendipity")
if (!word) exit()
const res = http.get(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`)
if (!res.ok) { alert("Not found", word); exit() }
const entry = res.json()[0]
print(`📖 ${entry.word}  ${entry.phonetic || ""}`)
entry.meanings.forEach(m => {
  print(`\n${m.partOfSpeech}`)
  m.definitions.slice(0, 3).forEach((d, i) => print(`  ${i + 1}. ${d.definition}`))
})
const audioURL = (entry.phonetics.find(p => p.audio) || {}).audio
audioURL ? audio.play(audioURL, { wait: true }) : speak(entry.word)
output(entry.meanings[0].definitions[0].definition)

