const s = state({ minutes: 25, left: 25 * 60, running: false })
let t = null

const tick = () => {
  s.left--
  if (s.left <= 0) {
    clearInterval(t); s.running = false; s.left = s.minutes * 60
    audio.melody([["C5", .15], ["E5", .15], ["G5", .3]])
    notify("Time's up!", "Take a break ☕️")
  }
}
const fmt = (sec) => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, "0")}`

ui.render(() =>
  VStack({ spacing: 24 },
    ZStack(
      Gauge(1 - s.left / (s.minutes * 60), { style: "circular", color: "red" }).scaleEffect(3),
    ).frame({ height: 200 }),
    Text(fmt(s.left)).font(56, "bold", "monospaced"),
    Stepper(`${s.minutes} minutes`, s.minutes, v => { s.minutes = v; if (!s.running) s.left = v * 60 }, { min: 1, max: 90 }),
    Button(s.running ? "Pause" : "Start", () => {
      s.running = !s.running
      if (s.running) t = setInterval(tick, 1000); else clearInterval(t)
    }).buttonStyle("borderedProminent").controlSize("large"),
  ).padding(24)
)

const today = new Date().toDateString()
const s = state({ habits: storage.get("habits", ["Drink water", "Read 10 pages", "Walk"]), done: storage.get("done-" + today, []), newHabit: "" })
const save = () => { storage.set("habits", s.habits); storage.set("done-" + today, s.done) }

ui.render(() =>
  List(
    Section(today,
      ForEach(s.habits, h =>
        Toggle(h, s.done.includes(h), on => {
          s.done = on ? [...s.done, h] : s.done.filter(x => x !== h)
          haptic(on ? "success" : "light"); save()
        }).contextMenu([{ title: "Delete", icon: "trash", destructive: true, action: () => { s.habits = s.habits.filter(x => x !== h); save() } }])
      ),
    ),
    Section("Progress", Gauge(s.done.length, { max: Math.max(1, s.habits.length), label: `${s.done.length}/${s.habits.length} done`, color: "purple" })),
    Section("Add",
      HStack(TextField("New habit", s.newHabit, v => s.newHabit = v),
        Button(Image("plus.circle.fill"), () => { if (s.newHabit) { s.habits = [...s.habits, s.newHabit]; s.newHabit = ""; save() } })),
    ),
  )
)

